import { existsSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
import { validateDispatchBody } from '/home/user/TLDR/.claudinite/shared/engine/scheduler/validate-dispatch.mjs';

const repoRoot = '/home/user/TLDR';
const body = process.argv[2];

const checks = JSON.parse(
  await (await import('node:fs/promises')).readFile(path.join(repoRoot, '.claudinite-checks.json'), 'utf8')
);
const declaredPacks = new Set(
  checks.packs.map((p) => (typeof p === 'string' ? p : p.id))
);

const result = validateDispatchBody(body, {
  exists: (p) => existsSync(path.join(repoRoot, p)),
  isPackDeclared: (id) => declaredPacks.has(id),
  loadTask: async (mjsPath) => (await import(pathToFileURL(path.join(repoRoot, mjsPath)).href)).default,
});

// loadTask above returns a Promise since dynamic import is async; validateDispatchBody
// calls it synchronously, so resolve manually here instead.
console.log(JSON.stringify(result, null, 2));

