import { existsSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
import { readFile } from 'node:fs/promises';
import { validateDispatchBody, dispatchFirstLine } from '/home/user/TLDR/.claudinite/shared/engine/scheduler/validate-dispatch.mjs';

const repoRoot = '/home/user/TLDR';
const body = process.argv[2];

const checks = JSON.parse(await readFile(path.join(repoRoot, '.claudinite-checks.json'), 'utf8'));
const declaredPacks = new Set(checks.packs.map((p) => (typeof p === 'string' ? p : p.id)));

const firstLine = dispatchFirstLine(body);
const mjsPath = firstLine.replace(/task\.md$/, 'task.mjs');
const preloadedDecl = existsSync(path.join(repoRoot, mjsPath))
  ? (await import(pathToFileURL(path.join(repoRoot, mjsPath)).href)).default
  : undefined;

const result = validateDispatchBody(body, {
  exists: (p) => existsSync(path.join(repoRoot, p)),
  isPackDeclared: (id) => declaredPacks.has(id),
  loadTask: (p) => {
    if (p !== mjsPath) throw new Error(`unexpected mjsPath ${p}`);
    if (preloadedDecl === undefined) throw new Error('module has no default export');
    return preloadedDecl;
  },
});

console.log(JSON.stringify(result, null, 2));

