1	// Scope-blind mechanism (no policy, no scope knowledge): given a built context
2	// and the discovered packs, run the ACTIVE packs' rules that a caller-supplied
3	// predicate admits, and return their findings. The world and work runners each
4	// call this with their own `includeRule` — this file never names a scope, so
5	// the two runners stay independent of each other while sharing the walk.
6	import { runRule } from './helpers/work.mjs';
7	import { isActive } from '../pack_loader/pack-registry.mjs';
8	
9	// A pack's contributedRules seam: the pack interprets the contributions other
10	// packs address to it on their manifests (`contributes`), returning first-class
11	// rules — how packs compose through declaration + configuration instead of
12	// importing each other's code. Isolated per pack, like manifest loading: one
13	// broken seam (a consumer-authored local pack's, say) must not sink the run.
14	// `onError` lets a caller turn a broken seam into a finding; passing none
15	// swallows it (a runner that doesn't own config diagnostics stays quiet).
16	export function contributedRules(pack, fromPacks, onError = null) {
17	  try { return pack.contributedRules?.(fromPacks) ?? []; }
18	  catch (e) { onError?.(e); return []; }
19	}
20	
21	// Every finding from the active packs' rules that `includeRule` admits. A rule
22	// turned `off` in settings is skipped. `onContributeError(pack, err)` is invoked
23	// when a pack's contributedRules seam throws (the caller decides whether that
24	// becomes a finding).
25	export function runActivePackRules(ctx, packs, { includeRule, onContributeError = null }) {
26	  const findings = [];
27	  // Expose the discovered packs to any rule that reasons about pack metadata
28	  // (e.g. the adoption-interview hygiene check reads each active pack's declared
29	  // questions) — checks run synchronously and can't re-discover packs themselves.
30	  ctx.packs = packs;
31	  const activePacks = packs.filter((p) => isActive(p, ctx.config));
